import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(API_URL):
    try:
        response = urllib.request.urlopen(API_URL)
        data = json.loads(response.read().decode())
        ip_match = re.search(IP_REGEX, str(data))
        if ip_match:
            return ip_match.group()
        else:
            return "No IP found"
    except Exception as e:
        return str(e)
